// 图标值统一带前缀存,和国旗(HK)、地球(globe:asia)区分开
export const BRAND_PREFIX = 'brand:'

export const isBrandIcon = (value?: string): boolean => /^brand:/i.test(String(value || ''))

export const findBrand = (value?: string): Brand | undefined => {
  if (!isBrandIcon(value)) return undefined
  const id = String(value).slice(BRAND_PREFIX.length).toLowerCase()
  return BRANDS.find((b) => b.id === id)
}

export const brandName = (b: Brand, locale: string): string => (locale.startsWith('zh') ? b.zh : b.en)
